// pxl-spec/cell/color.spec.rs
//
// GENERATED by script/spec.ts from color.json — do not edit.
//
// The color of every cube type: what a cube *is* to the eye when no
// texture is drawn over it — everything drawn with the pack off reads
// this, the coarse tiers included, which summarize it the way they
// summarize the tiles with the pack on
// (pxl-render mesh/chunk_mesher.rs). The shipped palette carries it as
// each row's `color`. A texture pack decorates these; it does not
// replace them, which is why this table lives with the type numbering in
// spec/cell rather than beside the pack's images.

// Casing here is the spec's and not Rust's: a name is spelled as the JSON
// spells it, so that one record is indexed by one name on both sides. To
// case them the way Rust would is to rename the protocol.

use super::cube_type::{cube_types, GroundChannelKey};
use super::r#type::Swatch;

/// `common`'s color for a type, by its number.
pub const fn common(t: u8) -> Option<Swatch> {
    match t {
        // A cell whose data is missing or invalid, a visible neutral gray so it reads as not known rather than as whatever drew last.
        cube_types::common::unknown => Some(Swatch::new(0xd9d0cc)),
        _ => None,
    }
}

